## ✅ Simple Code using malloc() and calloc()
```c
#include <stdio.h>
#include <stdlib.h>

int main() {
    int *p1, *p2;

    // malloc()
    p1 = (int*)malloc(2 * sizeof(int));
    p1[0] = 10;
    p1[1] = 20;

    printf("malloc: %d %d\n", p1[0], p1[1]);

    // calloc()
    p2 = (int*)calloc(2, sizeof(int));  // values will be 0

    printf("calloc: %d %d\n", p2[0], p2[1]);

    free(p1);
    free(p2);

    return 0;
}
```

